"""Append-only metadata change records generated by PostgreSQL."""
from datetime import datetime
from uuid import UUID

import sqlalchemy as sa
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import Mapped, mapped_column

from backend.app.database import Base


class MetadataAuditEvent(Base):
    __tablename__ = "metadata_audit_events"

    id: Mapped[UUID] = mapped_column(primary_key=True, server_default=sa.text("gen_random_uuid()"))
    entity_type: Mapped[str] = mapped_column(sa.String(20))
    entity_id: Mapped[UUID]
    equipment_id: Mapped[UUID | None] = mapped_column(sa.ForeignKey("equipment.id", ondelete="RESTRICT"))
    asset_id: Mapped[UUID | None] = mapped_column(sa.ForeignKey("equipment_assets.id", ondelete="RESTRICT"))
    actor_id: Mapped[UUID] = mapped_column(sa.ForeignKey("users.id", ondelete="RESTRICT"))
    action: Mapped[str] = mapped_column(sa.String(20))
    previous_values: Mapped[dict] = mapped_column(JSONB)
    new_values: Mapped[dict] = mapped_column(JSONB)
    occurred_at: Mapped[datetime] = mapped_column(
        sa.DateTime(timezone=True), server_default=sa.text("clock_timestamp()"),
    )
    entity_revision: Mapped[int] = mapped_column(sa.BigInteger)

    __table_args__ = (
        sa.CheckConstraint(
            "(entity_type = 'EQUIPMENT' AND equipment_id IS NOT NULL AND equipment_id = entity_id AND asset_id IS NULL) OR "
            "(entity_type = 'ASSET' AND asset_id IS NOT NULL AND asset_id = entity_id AND equipment_id IS NULL)",
            name="ck_metadata_audit_entity",
        ),
        sa.CheckConstraint("action = 'UPDATE'", name="ck_metadata_audit_action"),
        sa.CheckConstraint("entity_revision >= 1", name="ck_metadata_audit_revision"),
        sa.CheckConstraint(
            "jsonb_typeof(previous_values) = 'object' AND jsonb_typeof(new_values) = 'object' "
            "AND previous_values <> '{}'::jsonb AND previous_values <> new_values "
            "AND jsonb_path_query_array(previous_values, '$.keyvalue().key') = "
            "jsonb_path_query_array(new_values, '$.keyvalue().key')",
            name="ck_metadata_audit_diff",
        ),
        sa.UniqueConstraint("entity_type", "entity_id", "entity_revision", name="uq_metadata_audit_entity_revision"),
        sa.Index("ix_metadata_audit_actor_time", "actor_id", "occurred_at", "id"),
    )
